package com.epms.payroll.service;
import com.epms.payroll.entity.Employee; import com.epms.payroll.repository.EmployeeRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class EmployeeService {private final EmployeeRepository repo; private final AuditLogService audit; public EmployeeService(EmployeeRepository r,AuditLogService a){repo=r;audit=a;} public List<Employee> list(String q){return q==null||q.isBlank()?repo.findAll():repo.findByFirstNameContainingIgnoreCaseOrLastNameContainingIgnoreCaseOrEmployeeNumberContainingIgnoreCase(q,q,q);} public Employee get(Long id){return repo.findById(id).orElseThrow();} public Employee save(Employee e){return repo.save(e);} public Employee setActive(Long id, boolean active, String performedBy){Employee e=repo.findById(id).orElseThrow(); boolean old=e.isActive(); e.setActive(active); Employee saved=repo.save(e); audit.record("EMPLOYEE",id,"STATUS_CHANGE","active",old,active,performedBy,null); return saved;} public void delete(Long id){repo.deleteById(id);} }
